(()=>{'use strict';
const $=s=>document.querySelector(s);
if(!document.querySelector('.title-fauna')){let fauna=document.createElement('div');fauna.className='title-fauna';fauna.setAttribute('aria-hidden','true');fauna.innerHTML='<i class="tf tf-squid"></i><i class="tf tf-shark"></i><i class="tf tf-angler"></i><i class="tf tf-oarfish"></i>';document.getElementById('title')?.prepend(fauna)}
let modal=document.createElement('div');
modal.className='modal';
modal.id='resetDataModal';
modal.innerHTML='<div class="panel reset-panel"><div class="bigicon">⚠️</div><h2>このプレイヤーのデータをリセットしますか？</h2><p class="reset-warning">進行中の潜航、深海生物図鑑、称号・実績、アセンションの解放がすべて消えます。他のプレイヤーのデータは消えません。消去すると元に戻せません。</p><div class="reset-actions"><button class="btn" id="resetCancel">取り消す</button><button class="btn reset-confirm" id="resetConfirm">すべて消去</button></div></div>';
document.body.appendChild(modal);
let settingsMenu=document.createElement('div');settingsMenu.className='modal title-hub-modal';settingsMenu.id='titleSettingsModal';settingsMenu.innerHTML='<div class="panel title-hub-panel settings-hub-panel modal-shell"><header class="modal-shell-head"><div><small>GAME OPTIONS</small><h2>⚙️ 設定</h2></div></header><div class="modal-shell-body title-hub-grid settings-hub-grid"><section class="pc-audio-settings" aria-labelledby="pcAudioSettingsTitle"><header><i>♫</i><div><b id="pcAudioSettingsTitle">音量調整</b><small>PC版・設定は自動保存</small></div></header><label for="pcBgmVolume"><span>BGM</span><input id="pcBgmVolume" type="range" min="0" max="100" step="5" value="100"><output id="pcBgmVolumeValue" for="pcBgmVolume">100%</output></label><label for="pcSfxVolume"><span>効果音</span><input id="pcSfxVolume" type="range" min="0" max="100" step="5" value="100"><output id="pcSfxVolumeValue" for="pcSfxVolume">100%</output></label></section><button data-setting="guide" id="settingsGuide"><i>📘</i><span><b>はじめに・遊び方</b><small>初回の注意と説明を確認</small></span></button><button data-setting="profiles" id="settingsProfiles"><i>👤</i><span><b>プレイヤー</b><small id="settingsProfilesLabel"></small></span></button><button data-setting="runmod" id="settingsRunMod"><i>🌊</i><span><b>深海異変</b><small>深海異変 OFF</small></span></button><button data-setting="furi" id="settingsFuri"><i>あ</i><span><b>振り仮名</b><small>振り仮名 OFF</small></span></button><button data-setting="credits"><i>📜</i><span><b>クレジット</b><small>BGM制作者情報</small></span></button><button data-setting="debug" id="settingsDebug"><i>🛠</i><span><b>デバッグ</b><small>デバッグモード OFF</small></span></button><button data-setting="reset" class="danger"><i>↺</i><span><b>データリセット</b><small>すべての進行を消去</small></span></button></div><footer class="modal-shell-foot"><button class="btn" data-hub-close>閉じる</button></footer></div>';document.body.appendChild(settingsMenu);
let profileModal=document.createElement('div');profileModal.className='modal';profileModal.id='profileModal';profileModal.innerHTML='<div class="panel title-hub-panel modal-shell"><header class="modal-shell-head"><div><small>PLAYER SELECT</small><h2>👤 プレイヤー</h2></div></header><div class="modal-shell-body" id="profileList"></div><footer class="modal-shell-foot profile-add-row"><button class="btn gold" id="profileAddBtn">＋ 追加</button></footer><footer class="modal-shell-foot"><button class="btn" data-hub-close>閉じる</button></footer></div>';document.body.appendChild(profileModal);
function renderProfileList(){let list=$('#profileList'),profiles=window.abyssListProfiles?.()||[],activeId=window.abyssActiveProfileId?.();list.innerHTML=profiles.map(p=>{let active=p.id===activeId;return `<div class="profile-row ${active?'active':''}"><span class="profile-name">${p.name}${active?'　<b class="profile-current">選択中</b>':''}</span><span class="profile-actions">${active?'':'<button type=\"button\" data-switch=\"'+p.id+'\" class=\"btn\">切り替え</button>'}<button type="button" data-rename="${p.id}" class="btn">名前変更</button>${profiles.length>1?`<button type="button" data-delete="${p.id}" class="btn danger">削除</button>`:''}</span></div>`}).join('');window.applyFuri?.(list)}
function openProfileModal(){renderProfileList();profileModal.classList.add('on');window.applyFuri?.(profileModal)}
profileModal.onclick=e=>{if(e.target===profileModal||e.target.closest('[data-hub-close]'))return profileModal.classList.remove('on');let sw=e.target.closest('[data-switch]'),rn=e.target.closest('[data-rename]'),del=e.target.closest('[data-delete]');if(sw)window.abyssSwitchProfile?.(sw.dataset.switch);else if(rn){let cur=(window.abyssListProfiles?.()||[]).find(p=>p.id===rn.dataset.rename),name=prompt('新しい名前を入力してください',cur?.name||'');if(name&&name.trim()){window.abyssRenameProfile?.(rn.dataset.rename,name.trim());renderProfileList();syncProfilesLabel()}}else if(del){if(confirm('このプレイヤーのデータを削除しますか？元に戻せません。')){window.abyssDeleteProfile?.(del.dataset.delete);renderProfileList();syncProfilesLabel()}}};
$('#profileAddBtn').onclick=()=>{let name=prompt('追加するプレイヤーの名前を入力してください','');if(name&&name.trim())window.abyssCreateProfile?.(name.trim())};
function closeHub(menu){menu.classList.remove('on')}
const TOGGLES={runmod:{id:'settingsRunMod',label:'深海異変',isOn:()=>window.isAbyssRunModifierEnabled?.()||false,toggle:()=>window.toggleAbyssRunModifier?.()},debug:{id:'settingsDebug',label:'デバッグモード',isOn:()=>window.isAbyssDebugEnabled?.()||false,toggle:()=>window.toggleAbyssDebug?.()},furi:{id:'settingsFuri',label:'振り仮名',isOn:()=>window.isAbyssFuriEnabled?.()!==false,toggle:()=>window.toggleAbyssFuri?.()}};
function canUseDebug(){return window.abyssActiveProfileName?.()==='達也0726'}
function syncToggle(key){let t=TOGGLES[key],btn=$('#'+t.id);if(key==='debug')btn.hidden=!canUseDebug();let on=t.isOn();btn.classList.toggle('active',on);btn.querySelector('small').textContent=`${t.label} ${on?'ON':'OFF'}`}
function syncProfilesLabel(){let el=$('#settingsProfilesLabel');if(el)el.textContent=window.abyssActiveProfileName?.()||'プレイヤー1'}
function syncAudioSettings(){let prefs=window.getAbyssAudioPrefs?.()||{bgm:1,sfx:1};for(const [key,id]of [['bgm','pcBgmVolume'],['sfx','pcSfxVolume']]){let input=$('#'+id),value=$('#'+id+'Value'),percent=Math.round((Number(prefs[key])||0)*100);if(input)input.value=percent;if(value)value.textContent=percent+'%'}}
function changeAudioSetting(input,preview=false){let key=input.id==='pcBgmVolume'?'bgm':'sfx',percent=Math.max(0,Math.min(100,Number(input.value)||0)),prefs=window.setAbyssAudioPrefs?.({[key]:percent/100});$('#'+input.id+'Value').textContent=percent+'%';if(preview&&percent>0)window.previewAbyssSfx?.();return prefs}
$('#pcBgmVolume').addEventListener('input',e=>changeAudioSetting(e.currentTarget));$('#pcSfxVolume').addEventListener('input',e=>changeAudioSetting(e.currentTarget));$('#pcSfxVolume').addEventListener('change',e=>changeAudioSetting(e.currentTarget,true));
function openSettings(){Object.keys(TOGGLES).forEach(syncToggle);syncProfilesLabel();syncAudioSettings();settingsMenu.classList.add('on');window.applyFuri?.(settingsMenu)}
window.openAbyssSettings=openSettings;$('#titleSettingsMenu').onclick=openSettings;$('#battleSettingsView')?.addEventListener('click',openSettings);$('#titleRelicCodex').onclick=()=>window.openAbyssRelicCollection?.();
settingsMenu.onclick=e=>{if(e.target===settingsMenu||e.target.closest('[data-hub-close]'))return closeHub(settingsMenu);let action=e.target.closest('[data-setting]')?.dataset.setting;if(!action)return;if(TOGGLES[action]){TOGGLES[action].toggle();syncToggle(action);return}closeHub(settingsMenu);if(action==='guide')window.openAbyssTutorial?.();if(action==='reset')$('#resetAllData')?.click();if(action==='credits')window.openAbyssCredits?.();if(action==='profiles')openProfileModal()};
$('#titleBestiary').onclick=()=>window.openAbyssBestiary?.();
$('#resetAllData').onclick=()=>{modal.classList.add('on');window.applyFuri?.(modal)};
$('#resetCancel').onclick=()=>modal.classList.remove('on');
modal.onclick=e=>{if(e.target===modal)modal.classList.remove('on')};
$('#resetConfirm').onclick=async()=>{let b=$('#resetConfirm');b.disabled=true;b.textContent='消去中…';window.__abyssRunComplete=true;try{window.abyssResetActiveProfileData?.();window.__abyssRecoveredSave=null;await window.clearAbyssBackup?.()}catch(e){}location.reload()};
let newRunModal=document.createElement('div');newRunModal.className='modal';newRunModal.id='newRunConfirmModal';newRunModal.innerHTML='<div class="panel reset-panel"><div class="bigicon">🌊</div><h2>最初から潜りますか？</h2><p class="reset-warning">「つづきから」の中断データは削除され、今の潜航には戻れなくなります。</p><div class="reset-actions"><button class="btn" id="newRunCancel">取り消す</button><button class="btn gold" id="newRunConfirm">中断データを消して開始</button></div></div>';document.body.appendChild(newRunModal);let bypassNewRun=false,newButton=$('#newGame'),hasInterruptedRun=()=>{try{let x=JSON.parse(window.abyssStorageGet('abyssDeck')||'null');return !!(x&&Array.isArray(x.deck)&&x.deck.length&&x.hp>0)}catch(e){return false}},guardNewRun=e=>{if(bypassNewRun||!hasInterruptedRun())return;e.preventDefault();e.stopImmediatePropagation();newRunModal.classList.add('on');window.applyFuri?.(newRunModal)};newButton?.addEventListener('click',guardNewRun,true);newButton?.addEventListener('touchend',guardNewRun,true);$('#newRunCancel').onclick=()=>newRunModal.classList.remove('on');$('#newRunConfirm').onclick=()=>{newRunModal.classList.remove('on');try{window.abyssStorageRemove('abyssDeck');window.abyssStorageRemove('abyssDeckBackup')}catch(e){}window.__abyssRecoveredSave=null;bypassNewRun=true;newButton.click();setTimeout(()=>bypassNewRun=false,0)};newRunModal.onclick=e=>{if(e.target===newRunModal)newRunModal.classList.remove('on')};
const localInterruptedRun=hasInterruptedRun;hasInterruptedRun=()=>localInterruptedRun()||!!window.__abyssRecoveredSave;
window.abyssHasInterruptedRun=()=>hasInterruptedRun()&&!bypassNewRun;
window.applyFuri?.($('#title'));
})();
